// GetIntents: What a post can be.
func GetIntents() *Intents { return &teamboardValues().intents }

// GetFlags: The reporter's booleans.
func GetFlags() *Flags { return &teamboardValues().flags }

// GetStatuses: The post lifecycle.
func GetStatuses() *Statuses { return &teamboardValues().statuses }

// GetAssigneeMinRole: A post is owned by exactly one person, and never by a GM. Take = assign to yourself;
// a triager may assign to any eligible member.
func GetAssigneeMinRole() roles.Role { return teamboardValues().assigneeMinRole }

// GetTriageMinRole: The lowest role that may triage.
func GetTriageMinRole() roles.Role { return teamboardValues().triageMinRole }

// GetDeck: The deck's arrangements.
func GetDeck() *Deck { return teamboardValues().deck }

// GetColumns: The deck's columns, left to right.
func GetColumns() *Columns { return &teamboardValues().columns }

// GetSeverities: How bad a triaged post is.
func GetSeverities() *Severities { return &teamboardValues().severities }

// GetAreaGroups: The headers of the area picker.
func GetAreaGroups() *AreaGroups { return &teamboardValues().areaGroups }

// GetAreas: Where a post was seen.
func GetAreas() *Areas { return &teamboardValues().areas }

// GetInitialStatus: A new post starts here: the single status of the first column. The deck has at least
// two columns (`maxHidden` >= 1 is below their count), so `first()!` cannot fail.
func GetInitialStatus() *Status { return teamboardValues().initialStatus }

func GetInitialStatusID() StatusId { return teamboardValues().initialStatus.id }

// GetDefaultSeverity: The severity a triaged post gets unless the triager picks another. Exactly one
// exists: see the `default` check below.
func GetDefaultSeverity() *Severity { return teamboardValues().defaultSeverity }

func GetDefaultSeverityID() SeverityId { return teamboardValues().defaultSeverity.id }

var canTransitionTable = [6][6]bool{
	{false, true, false, false, true, true},
	{true, false, true, false, true, true},
	{true, false, false, true, false, false},
	{true, false, false, false, false, false},
	{true, false, false, false, false, false},
	{true, false, false, false, false, false},
}

// CanTransition: sovcommon's CanTransition.
func CanTransition(from StatusId, to StatusId) bool {
	return canTransitionTable[from][to]
}

var columnOfTable = sync.OnceValue(func() *[6]*Column {
	d := teamboardValues()
	return &[6]*Column{
		d.columns.At(0),
		d.columns.At(1),
		d.columns.At(2),
		d.columns.At(3),
		d.columns.At(3),
		d.columns.At(3),
	}
})

// ColumnOf: sovcommon's ColumnOf. `none` for a status no active column claims (only a retired
// status can be in that case), like the `(Column, bool)` it replaces.
func ColumnOf(s StatusId) *Column {
	return columnOfTable()[s]
}

